import React, { forwardRef } from 'react';

import { _useAppLink } from './hooks/useAppLink.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Link } from '../../typography/Link.js';

export interface AppLinkProps extends WithChildren, StylingProps, DataTestId {
  /** The ID of the app to which the link points. */
  appId: string;
  /** ID of the app page to be launched. */
  pageToken?: string;
}

/**
 * `AppLink` renders a link that points to the specified application.
 */
export const AppLink = /* @__PURE__ */ forwardRef<
  HTMLAnchorElement,
  AppLinkProps
>((props, forwardedRef) => {
  const {
    appId,
    pageToken,
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  } = props;
  const { onClick, href } = _useAppLink({ appId, pageToken });

  return (
    <Link
      ref={forwardedRef}
      onClick={onClick}
      href={href}
      data-testid={dataTestId}
      className={consumerClassName}
      style={consumerStyle}
      {...remainingProps}
    >
      {children}
    </Link>
  );
});

(AppLink as typeof AppLink & { displayName: string }).displayName = 'AppLink';
